namespace fs=std::filesystem;
constexpr qint64 manifestLimit=4*1024*1024;
constexpr uintmax_t assetLimit=512ull*1024*1024;
thread_local const fs::path* preparedMetadataTemp=nullptr;
[[noreturn]] void fail(const char* message){throw std::runtime_error(message);}
// Image codecs already use the \\?\ namespace. std::filesystem and Qt otherwise stop at MAX_PATH,
// so a written asset can be invisible and the rollback cannot remove it either.
fs::path ext(const fs::path& path){
    auto absolute=std::filesystem::absolute(path).lexically_normal();
    // A UNC share (`\\server\share`) is not root_name or root_path: MSVC keeps only `\\server` as the root.
    if(absolute==absolute.root_path()||absolute==absolute.root_name())return absolute;
    try{return imaging::win32FilePath(absolute);}
    catch(const std::invalid_argument& error){throw std::runtime_error(error.what());}
}
bool existsPath(const fs::path& p){return std::filesystem::exists(ext(p));}
bool isDir(const fs::path& p){return std::filesystem::is_directory(ext(p));}
bool isFile(const fs::path& p){return std::filesystem::is_regular_file(ext(p));}
uintmax_t fileBytes(const fs::path& p){return std::filesystem::file_size(ext(p));}
void createDir(const fs::path& p){std::filesystem::create_directory(ext(p));}
void renamePath(const fs::path& from,const fs::path& to){std::filesystem::rename(ext(from),ext(to));}
void removePath(const fs::path& p){std::filesystem::remove(ext(p));}
void removeAll(const fs::path& p){std::filesystem::remove_all(ext(p));}
fs::path qtPath(const fs::path& path){
    auto absolute=std::filesystem::absolute(path).lexically_normal();
    return absolute.native().size()<260?absolute:ext(absolute);
}
QString qs(const fs::path& p){return QString::fromStdWString(p.wstring());}
QString qstr(const std::string& s){return QString::fromUtf8(s.data(),qsizetype(s.size()));}
bool optional(const QJsonObject& o,const char* k){return !o.contains(k)||o.value(k).isNull();}
QJsonObject object(const QJsonValue& v){if(!v.isObject())fail("Required object missing or malformed");return v.toObject();}
QJsonArray array(const QJsonValue& v){if(!v.isArray())fail("Required array missing or malformed");return v.toArray();}
QString string(const QJsonValue& v){if(!v.isString())fail("Required string missing or malformed");return v.toString();}
bool boolean(const QJsonValue& v){if(!v.isBool())fail("Required Boolean missing or malformed");return v.toBool();}
double number(const QJsonValue& v){if(!v.isDouble()||!std::isfinite(v.toDouble()))fail("Required finite number missing or malformed");return v.toDouble();}
double bounded(const QJsonValue& v,double lo,double hi){auto n=number(v);if(n<lo||n>hi)fail("Numeric setting outside supported range");return n;}
int integer(const QJsonValue& v,int lo,int hi){auto n=bounded(v,lo,hi);if(std::trunc(n)!=n)fail("Integer expected");return int(n);}
QString uuid(const QJsonValue& value){auto s=string(value);QUuid id(s);if(s.size()!=36||s[8]!='-'||s[13]!='-'||s[18]!='-'||s[23]!='-')fail("Invalid UUID");auto normalized=id.toString(QUuid::WithoutBraces).toUpper();if(normalized.compare(s,Qt::CaseInsensitive)!=0)fail("Invalid UUID");return normalized;}
std::string optionalId(const QJsonObject&o,const char*k){return optional(o,k)?std::string{}:uuid(o[k]).toStdString();}
bool optionalBool(const QJsonObject&o,const char*k,bool fallback){return optional(o,k)?fallback:boolean(o[k]);}
double optionalNumber(const QJsonObject&o,const char*k,double fallback){return optional(o,k)?fallback:number(o[k]);}
void enumValue(const QJsonValue&v,std::initializer_list<const char*> values){auto s=string(v);if(std::none_of(values.begin(),values.end(),[&](const char*p){return s==p;}))fail("Unknown enum value");}
Transform transform(const QJsonValue&value){auto o=object(value);auto origin=array(o["origin"]),size=array(o["size"]);if(origin.size()!=2||size.size()!=2)fail("Foundation geometry requires two-number arrays");Transform t;
    t.x=number(origin[0]);t.y=number(origin[1]);t.width=number(size[0]);t.height=number(size[1]);t.rotation=number(o["rotation"]);t.flipX=boolean(o["flipX"]);t.flipY=boolean(o["flipY"]);
    auto sampling=string(o["sampling"]);if(sampling=="Nearest")t.sampling=Transform::Sampling::Nearest;else if(sampling=="Smooth")t.sampling=Transform::Sampling::Smooth;else if(sampling=="High quality")t.sampling=Transform::Sampling::High;else fail("Unknown sampling value");if(!t.valid())fail("Invalid layer transform");return t;}
QJsonObject encodeTransform(const Transform&t){return {{"origin",QJsonArray{t.x,t.y}},{"size",QJsonArray{t.width,t.height}},{"rotation",t.rotation},{"flipX",t.flipX},{"flipY",t.flipY},{"sampling",t.sampling==Transform::Sampling::Nearest?"Nearest":t.sampling==Transform::Sampling::Smooth?"Smooth":"High quality"}};}
void channel(const QJsonValue& v){enumValue(v,{"RGB","Red","Green","Blue"});}
void rangeName(const QJsonValue&v){enumValue(v,{"Master","Reds","Yellows","Greens","Cyans","Blues","Magentas"});}
void hsvTriplet(const QJsonObject&o){bounded(o["hue"],-360,360);bounded(o["saturation"],-100,100);bounded(o["lightness"],-100,100);}
void color(const QJsonValue&v){auto o=object(v);for(const char*k:{"red","green","blue"})bounded(o[k],0,1);}
void validateAdjustment(const QJsonObject&o){
    enumValue(o["kind"],{"Hue/Saturation","Levels","Curves","Exposure","Gradient Map","Grain","Invert","Black & White","Color Balance","Gaussian Blur","Motion Blur","Add Noise","Progressive Blur","Bloom / Glow","RGB Split","Vignette"});hsvTriplet(o);boolean(o["colorize"]);
    auto levels=object(o["levels"]);channel(levels["channel"]);auto ranges=array(levels["ranges"]);if(ranges.size()!=4)fail("Levels needs four ranges");
    for(auto v:ranges){auto r=object(v);auto black=bounded(r["black"],0,254);bounded(r["white"],black+1,255);bounded(r["gamma"],.1,9.99);bounded(r["outputBlack"],0,255);bounded(r["outputWhite"],0,255);}
    auto curves=object(o["curves"]);channel(curves["channel"]);auto channels=array(curves["channels"]);if(channels.size()!=4)fail("Curves needs four channels");
    for(auto v:channels){auto points=array(v);if(points.size()<2||points.size()>32)fail("Curve point count invalid");double last=-1;for(qsizetype i=0;i<points.size();++i){auto p=object(points[i]);auto x=bounded(p["x"],0,255);bounded(p["y"],0,255);if(x<=last||(i==0&&x!=0)||(i==points.size()-1&&x!=255))fail("Curve abscissae invalid");last=x;}}
    if(!optional(o,"hsvSettings")){auto h=object(o["hsvSettings"]);rangeName(h["range"]);boolean(h["colorize"]);boolean(h["invertRange"]);
        for(const char*k:{"adjustments","bands"}){auto pairs=array(h[k]);if(pairs.size()%2)fail("Enum dictionary must contain key/value pairs");for(qsizetype i=0;i<pairs.size();i+=2){rangeName(pairs[i]);auto v=object(pairs[i+1]);if(std::string(k)=="adjustments")hsvTriplet(v);else for(const char*field:{"falloffStart","rangeStart","rangeEnd","falloffEnd"})number(v[field]);}}}
    if(!optional(o,"exposureSettings")){auto e=object(o["exposureSettings"]);bounded(e["exposure"],-20,20);bounded(e["offset"],-.5,.5);bounded(e["gamma"],.01,9.99);}
    if(!optional(o,"gradientMapSettings")){auto g=object(o["gradientMapSettings"]);color(g["shadows"]);color(g["highlights"]);boolean(g["reversed"]);}
    if(!optional(o,"grainSettings")){auto g=object(o["grainSettings"]);bounded(g["amount"],0,100);bounded(g["size"],.5,20);bounded(g["roughness"],0,100);auto seed=bounded(g["seed"],0,4294967295.);if(std::trunc(seed)!=seed)fail("Grain seed must be UInt32");}
    if(!optional(o,"blackWhiteSettings")){auto g=object(o["blackWhiteSettings"]);for(const char*k:{"reds","yellows","greens","cyans","blues","magentas"})bounded(g[k],-200,300);}
    if(!optional(o,"colorBalanceSettings")){auto g=object(o["colorBalanceSettings"]);for(const char*tone:{"shadows","midtones","highlights"}){auto t=object(g[tone]);for(const char*k:{"cyanRed","magentaGreen","yellowBlue"})bounded(t[k],-100,100);}}
    if(!optional(o,"filterSettings")){auto g=object(o["filterSettings"]);bounded(g["radius"],0,250);bounded(g["angle"],-90,90);bounded(g["distance"],0,2000);bounded(g["amount"],0,400);boolean(g["gaussian"]);boolean(g["monochromatic"]);if(!optional(g,"seed")){auto seed=bounded(g["seed"],0,4294967295.);if(std::trunc(seed)!=seed)fail("Noise seed must be UInt32");}}
    if(!optional(o,"filterLayerSettings")){auto g=object(o["filterLayerSettings"]);if(!optional(g,"vignette")){auto v=object(g["vignette"]);bounded(v["amount"],0,100);color(v["color"]);bounded(v["midpoint"],0,100);bounded(v["roundness"],-100,100);bounded(v["feather"],0,100);bounded(v["highlights"],0,100);}if(!optional(g,"progressiveFrom"))bounded(g["progressiveFrom"],0,250);if(!optional(g,"progressiveTo"))bounded(g["progressiveTo"],0,250);auto point=[&](const char*k){if(optional(g,k))return;auto v=g[k];if(v.isArray()){auto a=array(v);if(a.size()!=2)fail("Invalid document point");number(a[0]);number(a[1]);return;}auto p=object(v);number(p["x"]);number(p["y"]);};point("progressiveStart");point("progressiveEnd");if(!optional(g,"progressiveRadial"))boolean(g["progressiveRadial"]);if(!optional(g,"progressiveInverted"))boolean(g["progressiveInverted"]);if(!optional(g,"bloomAmount"))bounded(g["bloomAmount"],0,100);if(!optional(g,"bloomRadius"))bounded(g["bloomRadius"],1,150);if(!optional(g,"rgbSplitDistance"))bounded(g["rgbSplitDistance"],0,200);if(!optional(g,"rgbSplitBlur"))bounded(g["rgbSplitBlur"],0,400);if(!optional(g,"rgbSplitAngle"))bounded(g["rgbSplitAngle"],-180,180);if(!optional(g,"rgbSplitRadial"))boolean(g["rgbSplitRadial"]);point("rgbSplitCenter");if(!optional(g,"rgbSplitReach"))bounded(g["rgbSplitReach"],1,100000);}
}
void validateShape(const QJsonObject&o,int version){
    if(optionalBool(o,"smoothing",false)&&string(o["kind"])!="Rectangle")fail("Only rectangles can have smooth corners");
    if(!optional(o,"lineStyle")||!optional(o,"lineCap")){
        if(version<15||string(o["kind"])!="Line")fail("Invalid styled line");
        if(!optional(o,"lineStyle"))enumValue(o["lineStyle"],{"Solid","Dashed","Long Dash","Dash Dot","Long Dash Dot","Dotted"});
        if(!optional(o,"lineCap"))enumValue(o["lineCap"],{"Round","Square"});
    }
    enumValue(o["kind"],{"Rectangle","Ellipse","Line"});for(const char*k:{"red","green","blue","cornerRadius"})number(o[k]);if(string(o["kind"])=="Line"){bounded(o["lineWidth"],.1,500);for(const char*end:{"start","end"}){auto p=object(o[end]);bounded(p["x"],0,1);bounded(p["y"],0,1);}}if(!optional(o,"stroke")){if(version<14)fail("Shape strokes require format v14");if(string(o["kind"])=="Line")fail("Line shapes cannot carry a stroke");auto s=object(o["stroke"]);bounded(s["width"],.1,500);for(const char*k:{"red","green","blue"})bounded(s[k],0,1);}}
Pixel colorPixel(const QJsonValue&v){auto o=object(v);auto ch=[](double x){return uint8_t(std::clamp(std::lround(x*255),0L,255L));};return {ch(bounded(o["red"],0,1)),ch(bounded(o["green"],0,1)),ch(bounded(o["blue"],0,1)),255};}
QJsonObject encodeColor(Pixel p){return {{"red",p.r/255.},{"green",p.g/255.},{"blue",p.b/255.}};}
Blend blendNamed(const QJsonValue&v){auto name=string(v);auto it=std::find_if(blendNames.begin(),blendNames.end(),[&](const char*n){return name==n;});if(it==blendNames.end())fail("Unknown blend mode");return Blend(it-blendNames.begin());}
void readShadow(const QJsonObject&o,EffectShadow&s){s.enabled=boolean(o["enabled"]);s.opacity=bounded(o["opacity"],0,1);s.angle=bounded(o["angle"],-360,360);s.distance=bounded(o["distance"],0,30000);s.size=bounded(o["size"],0,250);s.color=colorPixel(o["color"]);s.blend=blendNamed(o["blend"]);}
QJsonObject encodeShadow(const EffectShadow&s){return {{"enabled",s.enabled},{"opacity",s.opacity},{"angle",s.angle},{"distance",s.distance},{"size",s.size},{"color",encodeColor(s.color)},{"blend",blendNames.at(size_t(s.blend))}};}
void readGlow(const QJsonObject&o,EffectGlow&s){s.enabled=boolean(o["enabled"]);s.opacity=bounded(o["opacity"],0,1);s.size=bounded(o["size"],0,250);s.color=colorPixel(o["color"]);s.blend=blendNamed(o["blend"]);}
QJsonObject encodeGlow(const EffectGlow&s){return {{"enabled",s.enabled},{"opacity",s.opacity},{"size",s.size},{"color",encodeColor(s.color)},{"blend",blendNames.at(size_t(s.blend))}};}
void readEffects(const QJsonObject&o,LayerEffects&fx){fx.specified=true;if(!optional(o,"dropShadow"))readShadow(object(o["dropShadow"]),fx.dropShadow);if(!optional(o,"innerShadow"))readShadow(object(o["innerShadow"]),fx.innerShadow);if(!optional(o,"outerGlow"))readGlow(object(o["outerGlow"]),fx.outerGlow);if(!optional(o,"innerGlow"))readGlow(object(o["innerGlow"]),fx.innerGlow);if(!optional(o,"stroke")){auto s=object(o["stroke"]);fx.stroke.enabled=boolean(s["enabled"]);fx.stroke.size=bounded(s["size"],0,250);fx.stroke.color=colorPixel(s["color"]);fx.stroke.position=integer(s["position"],0,2);}if(!optional(o,"colorOverlay")){auto s=object(o["colorOverlay"]);fx.colorOverlay.enabled=boolean(s["enabled"]);fx.colorOverlay.opacity=bounded(s["opacity"],0,1);fx.colorOverlay.color=colorPixel(s["color"]);fx.colorOverlay.blend=blendNamed(s["blend"]);}}
QJsonObject encodeEffects(const LayerEffects&fx){QJsonObject o;if(fx.dropShadow.enabled||fx.dropShadow!=EffectShadow{})o["dropShadow"]=encodeShadow(fx.dropShadow);if(fx.innerShadow.enabled||fx.innerShadow!=EffectShadow{})o["innerShadow"]=encodeShadow(fx.innerShadow);if(fx.outerGlow.enabled||fx.outerGlow!=EffectGlow{})o["outerGlow"]=encodeGlow(fx.outerGlow);if(fx.innerGlow.enabled||fx.innerGlow!=EffectGlow{})o["innerGlow"]=encodeGlow(fx.innerGlow);if(fx.stroke.enabled||fx.stroke!=EffectStroke{})o["stroke"]=QJsonObject{{"enabled",fx.stroke.enabled},{"size",fx.stroke.size},{"color",encodeColor(fx.stroke.color)},{"position",fx.stroke.position}};if(fx.colorOverlay.enabled||fx.colorOverlay!=EffectOverlay{})o["colorOverlay"]=QJsonObject{{"enabled",fx.colorOverlay.enabled},{"opacity",fx.colorOverlay.opacity},{"color",encodeColor(fx.colorOverlay.color)},{"blend",blendNames.at(size_t(fx.colorOverlay.blend))}};return o;}
bool regularStyle(const std::string& style){return style.empty()||style=="Regular"||style=="Normal";}
bool textUsesExtended(const TextContent& text){if(text.alignment!=TextAlignment::Left||text.boxWidth||text.boxHeight||text.tracking!=0||text.leading!=0||!regularStyle(text.fontStyle))return true;for(const auto& run:text.fontRuns)if(!regularStyle(run.fontStyle))return true;return false;}
TextRun readRun(const QJsonObject&o,int units,bool font,int version){TextRun run;run.location=integer(o["location"],0,units);run.length=integer(o["length"],0,units-run.location);if(!font){run.hasColor=true;run.red=bounded(o["red"],0,1);run.green=bounded(o["green"],0,1);run.blue=bounded(o["blue"],0,1);}else{run.hasFont=true;run.fontFamily=string(o["fontFamily"]).toUtf8().toStdString();if(run.fontFamily.empty()||run.fontFamily.size()>256)fail("Invalid font run");run.fontSize=bounded(o["fontSize"],1,1000);if(!optional(o,"fontStyle")){if(version<12)fail("Font style requires format v12");run.fontStyle=string(o["fontStyle"]).toUtf8().toStdString();if(run.fontStyle.empty()||run.fontStyle.size()>256)fail("Invalid font style");}}return run;}
std::vector<TextRun> readRuns(const QJsonObject&o,const char*key,int units,bool font,int version){std::vector<TextRun> runs;if(optional(o,key))return runs;auto values=array(o[key]);if(values.size()>256)fail("Too many text runs");for(auto value:values)runs.push_back(readRun(object(value),units,font,version));return runs;}
QJsonObject parseJson(const QByteArray&bytes){QJsonParseError error;auto json=QJsonDocument::fromJson(bytes,&error);if(error.error!=QJsonParseError::NoError||!json.isObject())fail("Invalid JSON object");return json.object();}
int formatVersion(const Document&d){int version=d.cmykProfile?15:7;if(!d.guides.empty())version=std::max(version,8);for(const auto&l:d.layers){if(l.animation)version=std::max(version,18);if(l.deep)version=std::max(version,13);if(l.group&&l.opacity!=1)version=std::max(version,8);if(!l.adjustmentJson.empty()){auto a=parseJson(QByteArray::fromStdString(l.adjustmentJson));auto kind=string(a["kind"]);if(kind=="Vignette"||a.value("filterLayerSettings").toObject().contains("vignette"))version=std::max(version,20);if(kind=="Gaussian Blur"||kind=="Motion Blur"||kind=="Add Noise")version=std::max(version,9);if(kind=="Progressive Blur"||kind=="Bloom / Glow"||kind=="RGB Split"||a.contains("filterLayerSettings"))version=std::max(version,16);}if(l.text){if(!l.text->colorRuns.empty())version=std::max(version,10);if(!l.text->fontRuns.empty())version=std::max(version,11);if(textUsesExtended(*l.text))version=std::max(version,12);}if(!l.shapeJson.empty()){
        const auto shape=parseJson(QByteArray::fromStdString(l.shapeJson));
        if(shape.contains("stroke"))version=std::max(version,14);
        if(l.raster&&(!optional(shape,"lineStyle")||!optional(shape,"lineCap")))version=std::max(version,19);
        if(l.raster&&optionalBool(shape,"smoothing",false))version=std::max(version,17);
    }}return version;}
std::string jsonString(const QJsonObject&o){return QJsonDocument(o).toJson(QJsonDocument::Compact).toStdString();}
void noReparse(const fs::path&p){fs::path current;for(auto&part:fs::absolute(p).lexically_normal()){current/=part;if(current==current.root_name()||current==current.root_path())continue;auto native=current.native();const bool extendedUnc=native.starts_with(L"\\\\?\\UNC\\");const bool extendedDrive=native.starts_with(L"\\\\?\\")&&!extendedUnc&&native.size()>=7&&native[5]==L':'&&native[6]==L'\\';if(native.starts_with(L"\\\\?\\")&&!extendedDrive&&!extendedUnc)continue;if(extendedUnc){auto server=native.find(L'\\',8);auto share=server==std::wstring::npos?server:native.find(L'\\',server+1);if(share==std::wstring::npos||share+1>=native.size())continue;}auto attributes=GetFileAttributesW(ext(current).c_str());if(attributes==INVALID_FILE_ATTRIBUTES){auto error=GetLastError();if(error==ERROR_FILE_NOT_FOUND||error==ERROR_PATH_NOT_FOUND)continue;throw std::runtime_error("Could not inspect project path (Win32 "+std::to_string(error)+")");}if(attributes&FILE_ATTRIBUTE_REPARSE_POINT)fail("Project paths may not cross a reparse point");}}
void safeTree(const fs::path&p){noReparse(p);if(!existsPath(p))return;if(!isDir(p))fail("Expected package directory");for(auto&e:std::filesystem::recursive_directory_iterator(ext(p))){noReparse(e.path());if(!e.is_regular_file()&&!e.is_directory())fail("Unsupported package entry");}}
void removeTree(const fs::path&p){safeTree(p);if(existsPath(p))removeAll(p);}
QByteArray readFile(const fs::path&p,qint64 limit){noReparse(p);if(!isFile(p)||fileBytes(p)>uintmax_t(limit))fail("Project file absent or oversized");QFile file(qs(qtPath(p)));if(!file.open(QIODevice::ReadOnly))fail("Cannot read project file");auto data=file.read(limit+1);if(data.size()>limit||file.error()!=QFileDevice::NoError)fail("Project file read failed");return data;}
// Long paths cannot use QSaveFile. Metadata is written to a sibling temp file and replaces the
// destination only after the bytes are complete. A crash before that replace leaves the previous
// file readable. NewOnly can fail because the temp path already belongs to someone else, so the
// temp is deleted only when this call created it.
void commitBytes(const fs::path& destination,const QByteArray& bytes,const SaveFaultInjector* fault){
    if(destination.native().size()<260){QSaveFile file(qs(destination));file.setDirectWriteFallback(false);if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())fail("Cannot commit project metadata");return;}
    const bool replacing=GetFileAttributesW(destination.c_str())!=INVALID_FILE_ATTRIBUTES;
    struct Temp{fs::path path;bool created=false;~Temp(){if(created)QFile::remove(qs(path));}} temp;
    temp.path=destination;temp.path+=L".tmp-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64());
    if(fault&&*fault){preparedMetadataTemp=&temp.path;struct Reset{ ~Reset(){preparedMetadataTemp=nullptr;} } reset;(*fault)(SaveFaultPoint::BeforeMetadataTempCreate);}
    {QFile file(qs(temp.path));temp.created=file.open(QIODevice::WriteOnly|QIODevice::NewOnly);if(!temp.created||file.write(bytes)!=bytes.size()||!file.flush())fail("Cannot commit project metadata");auto handle=reinterpret_cast<HANDLE>(_get_osfhandle(int(file.handle())));if(handle==INVALID_HANDLE_VALUE||handle==nullptr||!FlushFileBuffers(handle))fail("Cannot commit project metadata");}
    if(replacing&&fault&&*fault)(*fault)(SaveFaultPoint::BeforeJournalReplace);
    if(!MoveFileExW(temp.path.c_str(),destination.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){auto error=GetLastError();throw std::runtime_error("Cannot commit project metadata (Win32 "+std::to_string(error)+")");}
    temp.created=false;
}
void writeJson(const fs::path&p,const QJsonObject&o,qint64 limit=manifestLimit,const SaveFaultInjector* fault=nullptr){auto bytes=QJsonDocument(o).toJson(QJsonDocument::Indented);if(bytes.size()>limit)fail("Project metadata exceeds size limit");noReparse(p);commitBytes(qtPath(p),bytes,fault);}
fs::path normalize(const fs::path&p){auto path=fs::absolute(p).lexically_normal();if(path.filename().empty()||path==path.root_path())fail("Invalid project destination");noReparse(path);if(!isDir(path.parent_path()))fail("Project parent directory does not exist");return path;}
fs::path suffix(const fs::path&p,const std::wstring&s){return p.parent_path()/(p.filename().wstring()+s);}
// A named mutex coordinates readers/writers without requiring write access merely to open
// a read-only package. Abandoned ownership is recoverable through the on-disk journal.
struct Lock {HANDLE handle{};explicit Lock(const fs::path&p){auto normalized=qs(p).toCaseFolded().toUtf8();uint64_t hash=14695981039346656037ull;for(char c:normalized){hash^=uint8_t(c);hash*=1099511628211ull;}auto name=L"Local\\CompositorProject-"+std::to_wstring(hash);handle=CreateMutexW(nullptr,FALSE,name.c_str());if(!handle)fail("Cannot create project coordination mutex");auto result=WaitForSingleObject(handle,0);if(result!=WAIT_OBJECT_0&&result!=WAIT_ABANDONED){CloseHandle(handle);handle=nullptr;fail("Project is busy in another process");}}~Lock(){if(handle){ReleaseMutex(handle);CloseHandle(handle);}}Lock(const Lock&)=delete;};
